-- Category-agnostic orders (plan: Stage 1 amendment, 2026-09-15).
--
-- `bookings` assumed one kind of job: one time block, a fixed price known in
-- advance, instant confirmation, no service address. It is replaced by
-- `orders` (what and who) and `appointments` (when), plus `quotes` and
-- `order_events`. How a service is delivered and sold becomes four settings
-- on business_services, with defaults on canonical_services; the engine and
-- agent read those, never the category id.
--
-- Generated by drizzle-kit, then edited by hand in two places: the
-- steps/default_steps backfills (a NOT NULL column can't be added to a
-- populated table without one), and the double-booking guard at the end.

CREATE TABLE "appointments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"business_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"resource_index" integer DEFAULT 0 NOT NULL,
	"scheduled_at" timestamp with time zone NOT NULL,
	"duration_min" integer NOT NULL,
	"buffer_min" integer DEFAULT 0 NOT NULL,
	"ends_at" timestamp with time zone DEFAULT now() NOT NULL,
	"status" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "appointments_kind_check" CHECK ("appointments"."kind" IN ('visit', 'pickup', 'delivery', 'job')),
	CONSTRAINT "appointments_status_check" CHECK ("appointments"."status" IN ('held', 'confirmed', 'completed', 'cancelled', 'no_show')),
	CONSTRAINT "appointments_resource_index_check" CHECK ("appointments"."resource_index" >= 0)
);
--> statement-breakpoint
CREATE TABLE "order_events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"actor" text NOT NULL,
	"type" text NOT NULL,
	"payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"delivered_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "order_events_actor_check" CHECK ("order_events"."actor" IN ('user', 'business', 'system'))
);
--> statement-breakpoint
CREATE TABLE "orders" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"search_id" uuid,
	"business_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"business_service_id" uuid NOT NULL,
	"status" text NOT NULL,
	"service_address" text,
	"service_lat" numeric(9, 6),
	"service_lng" numeric(9, 6),
	"quantity" numeric(10, 2),
	"details" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"price_aed" numeric(10, 2),
	"final_price_aed" numeric(10, 2),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "orders_status_check" CHECK ("orders"."status" IN ('requested', 'quoted', 'confirmed', 'in_progress', 'completed', 'declined', 'cancelled_by_user', 'cancelled_by_business', 'no_show')),
	CONSTRAINT "orders_service_location_check" CHECK (("orders"."service_lat" IS NULL) = ("orders"."service_lng" IS NULL))
);
--> statement-breakpoint
CREATE TABLE "quotes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"amount_aed" numeric(10, 2) NOT NULL,
	"est_duration_min" integer NOT NULL,
	"line_items" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"valid_until" timestamp with time zone NOT NULL,
	"status" text DEFAULT 'sent' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "quotes_status_check" CHECK ("quotes"."status" IN ('sent', 'accepted', 'declined', 'expired'))
);
