-- The double-booking guard moves from bookings (dropped above) to
-- appointments. 0001_booking_guard.sql explains why it looks like this — a
-- trigger-filled ends_at, btree_gist, a half-open range. Only the table
-- changes, plus `held` in the partial index: a requested order's appointment
-- occupies its slot until the business decides, so the business never
-- confirms a time that has gone. Declining cancels it and frees the slot.
ALTER FUNCTION set_booking_ends_at() RENAME TO set_appointment_ends_at;--> statement-breakpoint
CREATE TRIGGER appointments_ends_at
BEFORE INSERT OR UPDATE OF scheduled_at, duration_min, buffer_min ON appointments
FOR EACH ROW EXECUTE FUNCTION set_appointment_ends_at();--> statement-breakpoint
ALTER TABLE appointments ADD CONSTRAINT no_double_booking
EXCLUDE USING gist (
  business_id    WITH =,
  resource_index WITH =,
  tstzrange(scheduled_at, ends_at) WITH &&
) WHERE (status IN ('held','confirmed','completed'));